#!/bin/sh
# Dumps the memory behind metal_compositor_map() in the running WindowServer (three levels of pointers, 8 words each) to /Users/Shared/ws_mapdump.txt: the keys the Metal compositors are
# stored under (dtrace pid provider, root, a few seconds; move a window so that the map is used). The D program below was generated by a small script (nested copyin of 64 bytes).
# Run: sudo sh -c 'nohup sh /Users/Shared/ws_mapdump.sh >/dev/null 2>&1 &'
OUT=/Users/Shared/ws_mapdump.txt
ERR=/Users/Shared/ws_mapdump_err.txt
D=/Users/Shared/ws_mapdump.d
rm -f $OUT $ERR
PID=$(pgrep -x WindowServer | head -1)
echo "start $(date) WindowServer $PID" > $ERR
cat > $D <<'EOD'
int done;
pid$target:SkyLight:*metal_compositor_map*:return /!done/ { printf("MAP %p\n", arg1); this->b = (uint64_t *)copyin(arg1, 64); printf("L0 %x %x %x %x %x %x %x %x\n", this->b[0], this->b[1], this->b[2], this->b[3], this->b[4], this->b[5], this->b[6], this->b[7]); }
pid$target:SkyLight:*metal_compositor_map*:return /!done/ { this->b = (uint64_t *)copyin(arg1, 64); this->q = this->b[0]; }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->q >= 0x600000000000 && this->q < 0x700000000000/ { this->c = (uint64_t *)copyin(this->q, 64); printf("L1[0] %x: %x %x %x %x %x %x %x %x\n", this->q, this->c[0], this->c[1], this->c[2], this->c[3], this->c[4], this->c[5], this->c[6], this->c[7]); }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->q >= 0x600000000000 && this->q < 0x700000000000/ { this->c = (uint64_t *)copyin(this->q, 64); this->r = this->c[0]; }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->r >= 0x600000000000 && this->r < 0x700000000000/ { this->e = (uint64_t *)copyin(this->r, 64); printf("L2[0][0] %x: %x %x %x %x %x %x %x %x\n", this->r, this->e[0], this->e[1], this->e[2], this->e[3], this->e[4], this->e[5], this->e[6], this->e[7]); }
